import type { LimitedResource, PlanId } from "@/types/billing";
import type { FeatureFlagKey } from "@/types/feature-flag";

/**
 * The one place plan quotas are declared.
 *
 * `BillingService`, the invite flow, the project-create action, the webhook
 * settings page, the usage meter component and the seat-limit job all read
 * their numbers from here via `getPlanLimits()`. Adding a field to
 * `PlanLimits` therefore ripples into every one of those call sites — that
 * ripple is intentional and is what keeps the quotas honest.
 */
export interface PlanLimits {
  readonly plan: PlanId;
  readonly seats: number;
  readonly projects: number;
  readonly issuesPerProject: number;
  readonly storageMb: number;
  readonly apiRequestsPerHour: number;
  readonly webhooks: number;
  readonly retentionDays: number;
  readonly includedFlags: readonly FeatureFlagKey[];
  readonly priceCentsPerSeatMonthly: number;
}

/** `Infinity` is the sanctioned representation of "no limit". */
export const UNLIMITED = Number.POSITIVE_INFINITY;

export const PLAN_LIMITS: Readonly<Record<PlanId, PlanLimits>> = {
  free: {
    plan: "free",
    seats: 3,
    projects: 2,
    issuesPerProject: 100,
    storageMb: 100,
    apiRequestsPerHour: 100,
    webhooks: 0,
    retentionDays: 30,
    includedFlags: ["command_palette"],
    priceCentsPerSeatMonthly: 0,
  },
  starter: {
    plan: "starter",
    seats: 10,
    projects: 10,
    issuesPerProject: 1_000,
    storageMb: 2_000,
    apiRequestsPerHour: 1_000,
    webhooks: 2,
    retentionDays: 90,
    includedFlags: ["command_palette", "kanban_board", "csv_export"],
    priceCentsPerSeatMonthly: 900,
  },
  growth: {
    plan: "growth",
    seats: 50,
    projects: 100,
    issuesPerProject: 10_000,
    storageMb: 20_000,
    apiRequestsPerHour: 10_000,
    webhooks: 10,
    retentionDays: 365,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
      "issue_templates",
    ],
    priceCentsPerSeatMonthly: 1_900,
  },
  enterprise: {
    plan: "enterprise",
    seats: UNLIMITED,
    projects: UNLIMITED,
    issuesPerProject: UNLIMITED,
    storageMb: 500_000,
    apiRequestsPerHour: 100_000,
    webhooks: UNLIMITED,
    retentionDays: 2_555,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
      "issue_templates",
      "advanced_search",
      "public_projects",
      "ai_issue_summary",
    ],
    priceCentsPerSeatMonthly: 3_900,
  },
};

/** Plans ordered cheapest → richest; used for "at least this plan" checks. */
export const PLAN_ORDER: readonly PlanId[] = [
  "free",
  "starter",
  "growth",
  "enterprise",
];

export function getPlanLimits(plan: PlanId): PlanLimits {
  return PLAN_LIMITS[plan];
}

/** Reads one numeric quota without the caller destructuring `PlanLimits`. */
export function getLimit(plan: PlanId, resource: LimitedResource): number {
  return getPlanLimits(plan)[resource];
}

/** True when `plan` is at least as rich as `minPlan`. */
export function planAtLeast(plan: PlanId, minPlan: PlanId): boolean {
  return PLAN_ORDER.indexOf(plan) >= PLAN_ORDER.indexOf(minPlan);
}

/** True when consuming `requested` more units would breach the quota. */
export function wouldExceedLimit(
  plan: PlanId,
  resource: LimitedResource,
  used: number,
  requested = 1,
): boolean {
  return used + requested > getLimit(plan, resource);
}
"use client";

/**
 * Exposes the org's quotas to the UI.
 *
 * Must call (do not reimplement): getPlanLimits
 */
import { useCallback, useMemo } from "react";
import { getPlanLimits, type PlanLimits } from "@/config/plan-limits";
import type { LimitCheck, LimitedResource } from "@/types/billing";
import { useOrgContext } from "./use-org";

export function usePlanLimits(): {
  limits: PlanLimits;
  checks: readonly LimitCheck[];
  isExceeded: (resource: LimitedResource) => boolean;
} {
  const { org, limitChecks } = useOrgContext();
  const limits = useMemo(() => getPlanLimits(org.plan), [org.plan]);

  const isExceeded = useCallback(
    (resource: LimitedResource): boolean => {
      const check = limitChecks.find((c) => c.resource === resource);
      if (check !== undefined) return check.exceeded;
      // No measurement for this dimension yet: a quota of 0 is still a wall.
      return limits[resource] <= 0;
    },
    [limitChecks, limits],
  );

  return { limits, checks: limitChecks, isExceeded };
}
"use client";

/**
 * One plan tile rendering quotas straight from `PlanLimits`.
 *
 * The tile owns a click handler, so it has to be a Client Component: the
 * billing page is a Server Component, and a `<button onClick>` returned from
 * the server is a render error. `onSelect` is the page's inline Server
 * Action, which crosses this boundary legally.
 *
 * Must call (do not reimplement): getPlanLimits, can
 */
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { getPlanLimits, type PlanLimits } from "@/config/plan-limits";
import { FEATURE_FLAG_DEFINITIONS } from "@/config/feature-flags";
import { formatCents, formatLimit } from "@/lib/format";
import { can } from "@/lib/permissions";
import type { PlanId } from "@/types/billing";
import type { Actor } from "@/types/member";
import type { ReactElement } from "react";
import { billingResource } from "../permission/resources";

export type BillingPlanCardProps = {
  plan: PlanId;
  limits: PlanLimits;
  current: boolean;
  actor: Actor;
  onSelect: (plan: PlanId) => void;
};

export function BillingPlanCard(
  props: BillingPlanCardProps,
): ReactElement | null {
  const { plan, limits, current, actor, onSelect } = props;

  // The caller passes the limits it already has; re-reading the canonical row
  // keeps a stale prop from advertising a quota that no longer exists.
  const canonical = getPlanLimits(plan);
  const effective = canonical.plan === limits.plan ? limits : canonical;

  // Changing plans is an owner-only action; everyone else sees the tile
  // read-only rather than a button that would be refused.
  const mayChangePlan = can(actor, "org:manage_billing", billingResource(actor.orgId));

  return (
    <Card padded className={current ? "ring-2 ring-indigo-500" : undefined}>
      <CardHeader>
        <CardTitle>{plan}</CardTitle>
        {current ? (
          <Badge tone="brand" size="sm">
            Current
          </Badge>
        ) : null}
      </CardHeader>

      <CardContent>
        <p className="text-lg font-semibold">
          {formatCents(effective.priceCentsPerSeatMonthly)}
          <span className="text-sm font-normal text-neutral-500">
            {" "}
            / seat / month
          </span>
        </p>

        <ul className="mt-2 space-y-1 text-sm">
          <li>{formatLimit(effective.seats)} seats</li>
          <li>{formatLimit(effective.projects)} projects</li>
          <li>{formatLimit(effective.issuesPerProject)} issues per project</li>
          <li>{formatLimit(effective.storageMb)} MB storage</li>
          <li>{formatLimit(effective.webhooks)} webhooks</li>
          <li>{effective.retentionDays} days of history</li>
        </ul>

        {effective.includedFlags.length > 0 ? (
          <div className="mt-2 flex flex-wrap gap-1">
            {effective.includedFlags.map((flag) => (
              <Badge key={flag} tone="neutral" size="sm">
                {FEATURE_FLAG_DEFINITIONS[flag].label}
              </Badge>
            ))}
          </div>
        ) : null}
      </CardContent>
